"""
dependency_order.py

Implements plan_batches for topological batch scheduling.
"""

from collections import defaultdict, deque


def _collect_all_nodes(dependencies: dict[str, list[str]]) -> set[str]:
    """Return every node mentioned in the dependency map."""
    all_nodes: set[str] = set()
    for task, deps in dependencies.items():
        all_nodes.add(task)
        for dep in deps:
            all_nodes.add(dep)
    return all_nodes


def _build_graph(
    dependencies: dict[str, list[str]],
    all_nodes: set[str],
) -> tuple[dict[str, int], dict[str, list[str]]]:
    """Build in-degree map and adjacency list (dep -> dependents)."""
    in_degree: dict[str, int] = {node: 0 for node in all_nodes}
    dependents: dict[str, list[str]] = defaultdict(list)

    for task, deps in dependencies.items():
        for dep in set(deps):
            dependents[dep].append(task)
            in_degree[task] += 1

    return in_degree, dependents


def _apply_completed(
    completed: set[str],
    all_nodes: set[str],
    in_degree: dict[str, int],
    dependents: dict[str, list[str]],
) -> None:
    """Reduce in-degrees for dependents of already-completed tasks."""
    for node in completed:
        if node not in all_nodes:
            continue
        for dependent in dependents[node]:
            in_degree[dependent] -= 1


def _kahn_batches(
    remaining_nodes: set[str],
    in_degree: dict[str, int],
    dependents: dict[str, list[str]],
    completed: set[str],
) -> list[list[str]]:
    """Run Kahn's algorithm and return topological batches."""
    batches: list[list[str]] = []
    queue: deque[str] = deque(
        sorted(node for node in remaining_nodes if in_degree[node] == 0)
    )
    visited_count = 0

    while queue:
        current_batch = sorted(queue)
        batches.append(current_batch)
        visited_count += len(current_batch)

        queue.clear()
        next_level: list[str] = []
        for node in current_batch:
            for dependent in dependents[node]:
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0 and dependent not in completed:
                    next_level.append(dependent)
        for node in sorted(next_level):
            queue.append(node)

    if visited_count != len(remaining_nodes):
        raise ValueError("Cycle detected in dependency graph")

    return batches


def _validate_dependencies(dependencies: dict[str, list[str]]) -> None:
    """Validate the dependencies argument, raising TypeError or ValueError on bad input."""
    if not isinstance(dependencies, dict):
        raise TypeError(
            f"dependencies must be a dict, got {type(dependencies).__name__!r}"
        )
    for task, deps in dependencies.items():
        if not isinstance(task, str):
            raise TypeError(
                f"All task names must be strings; got key {task!r} of type "
                f"{type(task).__name__!r}"
            )
        if not isinstance(deps, list):
            raise TypeError(
                f"Dependencies for task {task!r} must be a list, got "
                f"{type(deps).__name__!r}"
            )
        for dep in deps:
            if not isinstance(dep, str):
                raise TypeError(
                    f"All dependency names must be strings; got {dep!r} of type "
                    f"{type(dep).__name__!r} in deps for task {task!r}"
                )
            if not dep:
                raise ValueError(
                    f"Dependency names must be non-empty strings; found empty string "
                    f"in deps for task {task!r}"
                )
        if not task:
            raise ValueError(
                f"Task names must be non-empty strings; got empty string as a key"
            )


def _validate_completed(completed: set[str] | None) -> None:
    """Validate the completed argument, raising TypeError on bad input."""
    if completed is None:
        return
    if not isinstance(completed, (set, frozenset)):
        raise TypeError(
            f"completed must be a set or None, got {type(completed).__name__!r}"
        )
    for item in completed:
        if not isinstance(item, str):
            raise TypeError(
                f"All items in completed must be strings; got {item!r} of type "
                f"{type(item).__name__!r}"
            )
        if not item:
            raise ValueError(
                "Items in completed must be non-empty strings; found empty string"
            )


def plan_batches(
    dependencies: dict[str, list[str]],
    *,
    completed: set[str] | None = None,
) -> list[list[str]]:
    """
    Given a dependency map {task: [prerequisite_tasks]}, return batches of
    tasks that can run in parallel. Each batch is sorted alphabetically.
    Raises ValueError if the graph contains a cycle.
    Raises TypeError if arguments are of incorrect types.

    If completed is provided, those tasks are treated as already done and
    omitted from the returned batches, but still satisfy dependencies for
    remaining tasks.
    """
    _validate_dependencies(dependencies)
    _validate_completed(completed)

    completed = set(completed) if completed else set()

    all_nodes = _collect_all_nodes(dependencies)
    in_degree, dependents = _build_graph(dependencies, all_nodes)
    _apply_completed(completed, all_nodes, in_degree, dependents)

    remaining_nodes = all_nodes - completed
    return _kahn_batches(remaining_nodes, in_degree, dependents, completed)

